import { useCallback, useEffect, useId, useRef, useState } from 'react';

export type NavKey = 'projects' | 'team' | 'settings' | 'logout';

export interface MenuDrawerProps {
  onNavigate: (key: NavKey) => void;
  label?: string;
}

type NavItem = { key: NavKey; label: string; danger?: boolean };

const PRIMARY_ITEMS: NavItem[] = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

const LOGOUT_ITEM: NavItem = { key: 'logout', label: 'Выйти', danger: true };

export default function MenuDrawer({ onNavigate, label = 'Меню' }: MenuDrawerProps) {
  const [open, setOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const panelId = useId();

  const close = useCallback(() => {
    setOpen(false);
    triggerRef.current?.focus();
  }, []);

  useEffect(() => {
    if (!open) return;
    panelRef.current?.querySelector<HTMLButtonElement>('button')?.focus();
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') close();
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [open, close]);

  const select = (key: NavKey) => {
    onNavigate(key);
    close();
  };

  const renderItem = ({ key, label: itemLabel, danger }: NavItem) => (
    <button
      key={key}
      type="button"
      className={danger ? 'jx-menu-item jx-menu-item--danger' : 'jx-menu-item'}
      onClick={() => select(key)}
    >
      {itemLabel}
    </button>
  );

  return (
    <>
      <button
        ref={triggerRef}
        type="button"
        className="jx-btn"
        aria-expanded={open}
        aria-controls={panelId}
        onClick={() => setOpen(true)}
      >
        {label}
      </button>

      {open && (
        <div className="jx-overlay">
          <div className="jx-overlay__backdrop" onClick={close} aria-hidden="true" />
          <div
            id={panelId}
            ref={panelRef}
            role="dialog"
            aria-modal="true"
            aria-label={label}
            className="jx-drawer jx-drawer--left jx-panel"
            style={{ padding: 'var(--jx-space-4)', gap: 'var(--jx-space-2)' }}
          >
            <nav className="jx-menu" aria-label={label}>
              {PRIMARY_ITEMS.map(renderItem)}
              <hr className="jx-menu-separator" />
              {renderItem(LOGOUT_ITEM)}
            </nav>
          </div>
        </div>
      )}
    </>
  );
}

